refentry.refsect1:
  &reftitle.description;

   arrayarray_slice
   arrayarray
   intoffset
   intnulllength&null;
   boolpreserve_keys&false;


array_slice ले offset र length parameters द्वारा तोकिए अनुसार array array from elements को sequence return गर्दछ।

  &reftitle.examples;



    array_slice का उदाहरणहरू


<?php
$input = array("a", "b", "c", "d", "e");

$output = array_slice($input, 2);      // returns "c", "d", and "e"
$output = array_slice($input, -2, 1);  // returns "d"
$output = array_slice($input, 0, 3);   // returns "a", "b", and "c"

// note the differences in the array keys
print_r(array_slice($input, 2, -1));
print_r(array_slice($input, 2, -1, true));
?>


    &example.outputs;


Array
(
    [0] => c
    [1] => d
)
Array
(
    [2] => c
    [3] => d
)







    array_slice र one-based array


<?php
$input = array(1 => "a", "b", "c", "d", "e");
print_r(array_slice($input, 1, 2));
?>


    &example.outputs;


Array
(
    [0] => b
    [1] => c
)







    मिश्रित keys सहित array_slice र array


<?php
$ar = array('a'=>'apple', 'b'=>'banana', '42'=>'pear', 'd'=>'orange');
print_r(array_slice($ar, 0, 3));
print_r(array_slice($ar, 0, 3, true));
?>


    &example.outputs;


Array
(
    [a] => apple
    [b] => banana
    [0] => pear
)
Array
(
    [a] => apple
    [b] => banana
    [42] => pear
)
